import sys

class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance

    def deposit(self, amount):
        self.balance += amount

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        print("Total Balance: 0")
        return

    initial_balance = float(lines[0].strip())
    num_deposits = int(lines[1].strip()) if len(lines) > 1 else 0

    account = BankAccount(initial_balance)

    deposits = []
    for line in lines[2:]:
        deposits.append(float(line.strip()))

    for i in range(min(num_deposits, len(deposits))):
        account.deposit(deposits[i])

    total = account.balance
    if total == int(total):
        print(f"Total Balance: {int(total)}")
    else:
        print(f"Total Balance: {total}")

if __name__ == "__main__":
    main()
